-- Unified projects. Legacy expense mappings remain for audit; fresh installations use the new reimbursement ledger.
CREATE TABLE zj_work_project (
id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,project_type VARCHAR(8) NOT NULL,project_no VARCHAR(255) NOT NULL UNIQUE,project_name VARCHAR(255) NOT NULL,contract_id BIGINT NULL,
client_name VARCHAR(255),site_address VARCHAR(500),contact_name VARCHAR(100),contact_phone VARCHAR(50),leader_user_id BIGINT,technical_user_id BIGINT,start_date DATE,end_date DATE,
details_json MEDIUMTEXT,registration_json TEXT,remark TEXT,legacy_number VARCHAR(255),number_pending BOOLEAN NOT NULL DEFAULT FALSE,classification_pending BOOLEAN NOT NULL DEFAULT FALSE,
created_by VARCHAR(64),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(64),updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,
FOREIGN KEY(contract_id) REFERENCES zj_contract_identity(id) ON DELETE RESTRICT,
CHECK(project_type IN ('WB','JC','PD','PG','QT')),INDEX idx_work_type(project_type,id),INDEX idx_work_contract(contract_id),INDEX idx_work_leader(leader_user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_legacy(project_id BIGINT NOT NULL,source_table VARCHAR(64) NOT NULL,source_id BIGINT NOT NULL,snapshot_json MEDIUMTEXT NOT NULL,PRIMARY KEY(source_table,source_id),FOREIGN KEY(project_id) REFERENCES zj_work_project(id) ON DELETE RESTRICT,INDEX idx_legacy_project(project_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_sequence(number_year INT NOT NULL,project_type VARCHAR(8) NOT NULL,sequence_value BIGINT NOT NULL,PRIMARY KEY(number_year,project_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_number(project_no VARCHAR(255) NOT NULL PRIMARY KEY,project_id BIGINT NOT NULL,allocated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES zj_work_project(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_issue(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,project_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,description TEXT,severity VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL,found_date DATE,resolved_date DATE,files TEXT,created_by VARCHAR(64),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES zj_work_project(id) ON DELETE RESTRICT,INDEX idx_issue_project(project_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_plan(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,project_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,plan_type VARCHAR(16) NOT NULL,start_date DATE NOT NULL,end_date DATE,status VARCHAR(16) NOT NULL,assignee_id BIGINT,remark TEXT,created_by VARCHAR(64),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES zj_work_project(id) ON DELETE RESTRICT,INDEX idx_plan_project(project_id,start_date,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_expense_link(project_id BIGINT NOT NULL,source_cost_id INT NOT NULL UNIQUE,user_id BIGINT NULL,PRIMARY KEY(project_id,source_cost_id),FOREIGN KEY(project_id) REFERENCES zj_work_project(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE zj_work_project_migration(version VARCHAR(64) NOT NULL PRIMARY KEY,applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,report_json MEDIUMTEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
